"""Batch 9 (EP41-EP45) editorial content: "Pemicu Kecil, Dampak Raksasa". Executed inside epdata.py, so EPS and WP come from there."""
RD9 = "Dibaca 9 Nov 2026"


def _b9(rows):
    return {f"s{i+1}": r for i, r in enumerate(rows)}


def _ep9(**k):
    k.setdefault("alts", [])
    return k


